function simTab(){const r=byId(RECS,A.sim.rec)||RECS[0],u=byId(USERS,A.sim.user)||USERS[0],res=evalAccess(u,r),eff=effLabel(r);
 const all=USERS.map(x=>({u:x,r:evalAccess(x,r)})),yes=all.filter(a=>a.r.allow);
 const ico2=s=>({pass:"✓",fail:"✕",skip:"–"}[s]);
 return `<div class="card glass"><div class="cardhead"><div><h3>Who can see this?</h3><span class="muted small" data-role="story">Pick a record and a person. The engine runs the same rules production runs and shows each step, so a denial is never a mystery.</span></div></div>
 <div class="grid g2" style="gap:12px"><label class="fld"><span class="flab">Record</span><select class="fin" data-adm-in="simrec">${recOpt()}</select></label><label class="fld"><span class="flab">Person or agent</span><select class="fin" data-adm-in="simuser">${USERS.map(x=>`<option value="${x.id}" ${A.sim.user===x.id?"selected":""}>${esc(x.n)} · ${esc(x.title)}</option>`).join("")}</select></label></div></div>
 <div class="grid g2" style="align-items:start"><div class="card glass"><div class="row sp"><div><div class="eyebrow">Decision</div><div class="adm-dec ${res.allow?"ok":"no"}" role="status"><span>${res.allow?"Allow":"Deny"}</span><small>${esc(u.n)} ${res.allow?"can":"cannot"} see <b>${esc(r.n)}</b>${res.bg?" through break-glass":""}</small></div></div>${pill(LABELS[res.label],LBL_CLS[res.label])}</div>
 <dl class="kv" style="grid-template-columns:110px 1fr"><dt>Person</dt><dd>${esc(u.n)}, ${esc(u.dept)}, ${esc(u.loc)}, device ${esc(u.dev)}, clearance ${LABELS[u.clr]}</dd><dt>Roles</dt><dd>${esc(roleNames(u))}</dd><dt>Record</dt><dd>${esc(r.tn)} owned by ${esc(r.owner)}, ${esc(r.dept)}${eff.why?`, label raised by <b>${esc(eff.why.from)}</b>`:""}</dd></dl>
 ${res.allow?"":`<div class="hint" style="display:block;background:var(--warn-s);color:var(--warn)"><b>What would change the answer:</b> ${esc((res.deny&&res.deny.fix)||"A different role or an approved break-glass request.")}</div>
 <div class="row" style="margin-top:10px"><button class="btn" data-adm="bgfor:${u.id}:${esc(r.id)}">Request break-glass for this</button></div>`}</div>
 <div class="card glass"><div class="cardhead"><h3>Evaluation trace</h3><span class="muted small">${res.steps.length} steps, in order</span></div><ol class="adm-trace">${res.steps.map(s=>`<li class="${s.res}"><i aria-hidden="true">${ico2(s.res)}</i><div><b>${esc(s.t)}</b> ${pill(s.res==="pass"?"Passed":s.res==="fail"?"Denied here":"Not applicable",ST_CLS[s.res])}<div class="small muted">${s.d}</div></div></li>`).join("")}</ol></div></div>
 <div class="card glass"><div class="cardhead"><div><h3>Who can see ${esc(r.n)}</h3><span class="muted small" data-role="story"><b>${yes.length}</b> of ${all.length} people and agents can see it; <b>${all.length-yes.length}</b> cannot. Select a name to load their trace.</span></div></div>
 <div class="adm-people">${all.map(a=>`<button class="adm-person ${a.r.allow?"ok":"no"}" data-adm="simu:${a.u.id}"><span class="dot ${a.r.allow?"good":"bad"}"></span><span><b>${esc(a.u.n)}</b><br><span class="muted small">${a.r.allow?(a.r.bg?"Allowed by break-glass":"Allowed"):"Denied: "+esc((a.r.deny||{}).t||"")}</span></span></button>`).join("")}</div></div>`}
