function wiHTML(){const r=whatif(),best=r.reduce((a,b)=>b.total<a.total?b:a),cur=r.find(x=>x.p.cur);
 return `<div class="adm-wi">${r.map(x=>`<div class="adm-wip ${x.p===best.p?"best":""}"><b>${x.p.n}</b>${x.p.cur?pill("Current","info"):""}${x.p===best.p?pill("Cheapest","good"):""}<span class="num" style="font-size:28px" data-role="metric">${usd(x.total)}</span><span class="muted small">${usd(x.p.base)} base + ${usd(x.seat)} seats${x.tokOv+x.apiOv>0?` + ${usd(x.tokOv+x.apiOv)} overage`:""}</span>${x.p!==cur?`<span class="small ${x.total<cur.total?"good":"warn"}" style="font-weight:700">${x.total<cur.total?"Saves ":"Costs "}${usd(Math.abs(x.total-cur.total))} a month vs current</span>`:""}</div>`).join("")}</div><p class="muted small"><span class="fx">Total = base fee + Σ(seats × seat price) + overage above plan quota × rate × plan multiplier</span></p>`}
