A.cfw=A.cfw||"all";
const CUR=c=>c.ev==="auto"||c.ev==="manual";
function ctlCalc(){const p=Math.round(A.ctl.filter(CUR).length/A.ctl.length*100);METRICS.m_ctrl.cur=p;METRICS.m_ctrl.tr[7]=p;return p}
const EVL={auto:["Automated","good"],manual:["Collected","good"],stale:["Stale","warn"],missing:["Missing","bad"]};
function ctlTab(){const p=ctlCalc(),L=A.cfw==="all"?A.ctl:A.ctl.filter(c=>c.fw===A.cfw),gaps=A.ctl.filter(c=>!CUR(c)),fws=["SOC 2","ISO 27001","NIST AI RMF"];
 return `<div class="card glass"><div class="cardhead"><div><h3>Compliance control library</h3><span class="muted small" data-role="story"><b>${A.ctl.filter(CUR).length}</b> of ${A.ctl.length} controls have current evidence (<b>${p}%</b>). ${gaps.length?"The gaps: "+gaps.map(g=>"<b>"+g.ref+"</b> "+(g.ev==="missing"?"has no evidence at all":"is stale, last evidenced "+g.last)).join("; ")+".":"No gaps."}</span></div><div class="row">${fchip("m_ctrl")}</div></div>
 <div class="row" style="margin-bottom:12px"><button class="chip" data-adm="cfw:all" aria-pressed="${A.cfw==="all"}">All frameworks</button>${fws.map(f=>`<button class="chip" data-adm="cfw:${f}" aria-pressed="${A.cfw===f}">${f} (${A.ctl.filter(c=>c.fw===f).length})</button>`).join("")}</div>
 <div class="tablewrap" style="max-height:none"><table class="adm-tbl" style="min-width:820px"><thead><tr><th>Control</th><th>What it requires</th><th>Where Oukala meets it</th><th>Owner</th><th>Evidence</th></tr></thead><tbody>${L.map(c=>`<tr><td><b>${c.ref}</b><br><span class="muted small">${c.fw}</span></td><td class="small">${esc(c.t)}</td><td>${esc(c.feat)}</td><td>${esc(c.own)}</td><td><button class="adm-ev" data-adm="ctl:${c.id}">${pill(EVL[c.ev][0],EVL[c.ev][1])} <span class="muted small">${c.last}</span></button></td></tr>`).join("")}</tbody></table></div></div>
 ${gaps.length?`<div class="card glass"><div class="cardhead"><h3>Gaps story</h3>${aiChip({model:"Claude Sonnet",conf:.87,title:"Gap analysis",note:"Compares the evidence each control needs with what the platform can collect on its own, and proposes the cheapest way to close each gap.",src:["Control library","Evidence index","Audit log"],guards:["Does not mark a control as met"]})}</div><div class="needs">${gaps.map(g=>`<div class="need"><div class="ico ${g.ev==="missing"?"bad":"warn"}">${ico("warn")}</div><div><b>${g.fw} ${g.ref}: ${esc(g.t)}</b><span class="muted">${g.ev==="missing"?"No evidence exists.":"Evidence is out of date."} ${g.id==="c8"?"Sensitivity labels and the guardrail redaction logs can serve as evidence once exported monthly.":g.id==="c15"?"The spend and override metrics already exist; schedule a monthly snapshot into the evidence index.":g.id==="c3"?"The Q4 access review will replace the July evidence when it closes on Oct 30.":"Re-run the red-team set and attach the report."}</span></div><button class="btn" data-adm="ctl:${g.id}">Close the gap</button></div>`).join("")}</div></div>`:""}`}
