A.ret=A.ret||[{id:"d1",n:"Audit log",yrs:84,act:"Archive",n2:"7 years, then moved to cold storage",vol:"4,812 entries a month"},{id:"d2",n:"AI prompts and outputs",yrs:13,act:"Delete",n2:"13 months",vol:"38K calls a month"},{id:"d3",n:"Invoices and approvals",yrs:84,act:"Archive",n2:"7 years",vol:"180 a month"},{id:"d4",n:"Meeting transcripts",yrs:3,act:"Delete",n2:"90 days",vol:"95 meetings a month"},{id:"d5",n:"Incident records",yrs:60,act:"Anonymize",n2:"5 years, then names removed",vol:"420 a month"},{id:"d6",n:"Knowledge drafts",yrs:36,act:"Delete",n2:"3 years",vol:"60 a month"},{id:"d7",n:"Database backups",yrs:1,act:"Delete",n2:"35 days",vol:"Daily"}];
const RET_TXT=m=>m>=12?(m%12?m+" months":m/12+" year"+(m/12>1?"s":"")):(m<=3&&m>0&&m!==1?m+" months":m+" month");
A.holds=A.holds||[{id:"h1",n:"Lumen SOW-4 dispute",cust:["Maya Ortiz","Tom Becker"],scope:["Contract","Invoice","Meeting transcript"],why:"Possible dispute over milestone 3 acceptance.",on:"Oct 5",exp:"Until released by Legal",recs:38,st:"active"}];
