function retTab(){const act=A.holds.filter(h=>h.st==="active"),frozen=act.reduce((a,h)=>a+h.recs,0);
 return `<div class="grid g2" style="align-items:start"><div class="card glass"><div class="cardhead"><div><h3>Retention policies</h3><span class="muted small" data-role="story">How long each kind of data is kept and what happens at the end. A legal hold always wins over a schedule. Next purge: <b>1,204</b> transcripts on Oct 21, minus <b>${act.some(h=>h.scope.includes("Meeting transcript"))?22:0}</b> under hold.</span></div></div>
 ${A.ret.map(r=>`<div class="adm-line"><span><b>${esc(r.n)}</b><br><span class="muted small">${esc(r.vol)}</span></span><span class="row">${pill("Keep "+RET_TXT(r.yrs),"info")}${pill(r.act,r.act==="Delete"?"warn":"mute")}<button class="btn quiet" data-adm="retedit:${r.id}" aria-label="Edit retention for ${esc(r.n)}">Edit</button></span></div>`).join("")}</div>
 <div class="card glass"><div class="cardhead"><div><h3>Legal holds</h3><span class="muted small" data-role="story"><b>${act.length}</b> active hold${act.length===1?"":"s"} freeze <b>${frozen}</b> records. Frozen records cannot be edited, deleted or purged, and each access is logged.</span></div><button class="btn primary" data-adm="holdnew">New legal hold</button></div>
 ${A.holds.map(h=>`<div class="adm-line"><span><b>${esc(h.n)}</b> ${pill(h.st==="active"?"Active":"Released",h.st==="active"?"warn":"mute")}<br><span class="muted small">${esc(h.why)}<br>Custodians: ${h.cust.map(esc).join(", ")} · Scope: ${h.scope.map(esc).join(", ")} · since ${h.on} · ${h.recs} records</span></span>${h.st==="active"?`<button class="btn" data-adm="holdrel:${h.id}">Release</button>`:""}</div>`).join("")||empty("No holds","Nothing is frozen.")}</div></div>`}
function auditHTML(){const all=ALLA(),p=ctlCalc();
 return `<div class="screen kfast">${hero("Platform · Audit and compliance","Prove what happened, and who or what did it",`The log holds <b>${all.length}</b> entries, <b>${all.filter(x=>x.kind==="agent").length}</b> of them by AI agents. <b>${p}%</b> of the <b>${A.ctl.length}</b> controls across SOC 2, ISO 27001 and the NIST AI Risk Management Framework have current evidence. <b>${A.holds.filter(h=>h.st==="active").length}</b> legal hold freezes records for the Lumen dispute.`,`<div class="row">${fchip("m_ctrl")}${aiChip({model:"Claude Sonnet",conf:.87,title:"Gap analysis",note:"Maps controls to platform features and drafts the gap story. Evidence status is computed, not generated.",src:["Control library","Audit log"],guards:["Cannot mark a control as met"]})}</div>`)}${lensNote()}
 ${views("adm_audit",["Audit log","Controls","Retention and holds"],[logTab(),ctlTab(),retTab()])}</div>`}
