function modForm(){openF({id:"adm_mod",title:"Add a model for review",story:"New models start in review and are never routed to until someone approves them. Data residency and zero-retention terms decide where they can be used.",submit:"Send for review",fields:[{k:"n",label:"Model name",type:"text",req:true},{k:"prov",label:"Provider",type:"text",req:true},{k:"pin",label:"Input price per million tokens",type:"number",min:0,step:0.1},{k:"pout",label:"Output price per million tokens",type:"number",min:0,step:0.1},{k:"res",label:"Data residency",type:"select",opts:["US region","US and EU","US East, private endpoint","Meridian Azure, no egress","Unknown"]},{k:"zdr",label:"Zero data retention",type:"toggle"},{k:"max",label:"Highest label it may see",type:"chips",opts:LABELS.map((l,i)=>[String(i),l])}],defaults:{res:"US region",max:"1"},onSubmit:v=>{A.models.push({id:slug(v.n),n:v.n,prov:v.prov,pin:+v.pin||1,pout:+v.pout||4,lat:1.5,q:75,res:v.res,zdr:!!v.zdr,st:"review",max:+v.max||0});audit("added model for review",v.n);setTimeout(render,0);return {toast:v.n+" is in review"}}})}
