function ctlDrawer(id){const c=byId(A.ctl,id);openDrawer(`<span class="pill info">${c.fw} · ${c.ref}</span><h2 style="font-size:26px;margin:12px 0 6px;padding-right:60px">${esc(c.t)}</h2><div class="row">${pill(EVL[c.ev][0]+(c.req?" (requested)":""),EVL[c.ev][1])}<span class="muted small">Last evidence ${c.last} · owner ${esc(c.own)}</span></div><p class="story" data-role="story" style="font-size:16px;margin:12px 0">${CUR(c)?"Evidence is current."+(c.ev==="auto"?" Oukala collects it on its own, so the auditor can pull it any time.":""):c.ev==="missing"?"No evidence exists yet, so an auditor would mark this control as not tested.":"Evidence is older than the review period, so an auditor would ask for a fresh sample."}</p><div class="eyebrow" style="margin-bottom:6px">Evidence</div>${c.items.length?c.items.map(i=>`<div class="adm-line"><span>${esc(i)}</span>${pill(c.ev==="stale"?"Out of date":"Attached",c.ev==="stale"?"warn":"good")}</div>`).join(""):'<div class="muted small">Nothing attached.</div>'}<div class="row" style="margin-top:14px">${c.ev==="missing"?`<button class="btn primary" data-adm="ctlreq:${c.id}">Request evidence</button>`:`<button class="btn primary" data-adm="ctlcol:${c.id}">Collect fresh evidence now</button>`}<button class="btn" data-go="${c.go}">Open ${esc(c.feat)}</button></div>`);audit("opened control",c.ref)}

