document.addEventListener("input",e=>{const t=e.target,k=t.dataset&&t.dataset.admIn;if(!k)return;const [a,x,y]=k.split(":");
 if(a==="th_name"){A.theme.name=t.value;updTheme()}else if(a==="th_primary"||a==="th_accent"){A.theme[a.slice(3)]=t.value;const c=t.parentNode.querySelector("code");if(c)c.textContent=t.value;updTheme()}else if(a==="th_radius"){A.theme.radius=+t.value;const o=document.getElementById("adm_radv");if(o)o.textContent=t.value+"px";updTheme()}
 else if(a==="wi_seats"||a==="wi_tok"||a==="wi_api"){const w=A.wi||(A.wi={seats:138,tok:100,api:5}),f=a.slice(3);w[f]=+t.value;const o=document.getElementById("adm_wi_"+f);if(o)o.textContent=t.value+(f==="seats"?"":"M");document.getElementById("adm_wires").innerHTML=wiHTML()}
 else if(a==="gt_prompt"||a==="gt_ans"){A.gt[a==="gt_prompt"?"prompt":"ans"]=t.value;document.getElementById("adm_gtres").innerHTML=gtHTML()}
 else if(a==="af_rec"){A.af.rec=t.value;A.af.n=25;document.getElementById("adm_loglist").innerHTML=logRows()}});
document.addEventListener("change",e=>{const t=e.target,k=t.dataset&&t.dataset.admIn;if(!k)return;const [a,x,y]=k.split(":");
 switch(a){
 case "persona":A.asPersona=t.value;delete FORMST.admprev;return rr();
 case "vsort":A.cols[A.obj].sort=t.value;return rr();case "vdir":A.cols[A.obj].dir=t.value;return rr();case "vgroup":A.cols[A.obj].group=t.value;return rr();
 case "th_font":A.theme.font=t.value;return updTheme();
 case "th_logo":{const f=t.files&&t.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{A.theme.logo=rd.result;audit("uploaded logo",f.name);toast("Logo added to the preview","good");updTheme()};rd.readAsDataURL(f);return}
 case "str":{const l=A.lang;(A.ov[l]=A.ov[l]||{});if(t.value.trim())A.ov[l][x]=t.value;else delete A.ov[l][x];audit("edited string",l+" · "+x);return rr()}
 case "lblrec":A.lblRec=t.value;return rr();
 case "simrec":A.sim.rec=t.value;return rr();case "simuser":A.sim.user=t.value;return rr();
 case "rttask":A.rt.task=t.value;return rr();
 case "tok":{const o=byId(A.tok,x);o[y]=y==="model"?t.value:+t.value;audit("changed tokenomics input",o.n+" · "+y);return rr()}
 case "agcap":A.bud.ag[x]=+t.value;audit("changed agent cap",x+" · "+usd(+t.value));return rr();
 case "af_actor":A.af.actor=t.value;A.af.n=25;return rr();case "af_action":A.af.action=t.value;A.af.n=25;return rr();
 }});

